parameters.jsCode:
// 1. Respuesta del nodo anterior (Gemini)
const geminiResponse = $input.first().json;

// 2. Datos del cultivo (del Webhook que mandó WF1)
const cultivoData = $('Webhook').first().json.body || $('Webhook').first().json;

// 3. Validación POSITIVA: verificamos que la respuesta contenga lo que esperamos,
//    en vez de asumir que "no falló" equivale a "es un diagnóstico" (ver 16.14).
let diagnosis;
const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  // Gemini no devolvió diagnóstico (503, cuota agotada, error de red).
  // NO guardamos el error como si fuera un diagnóstico.
  diagnosis = {
    diagnostico_visual: null,
    diagnostico_tecnico: 'La IA no pudo analizar la foto en este intento.',
    severidad: 'desconocida',
    plagas_detectadas: [],
    acciones_inmediatas: ['Reintentar el diagnóstico más tarde.'],
    recomendaciones_mediano_plazo: [],
    explicacion_agricultor: 'No se pudo generar el diagnóstico visual. La alerta del sistema experto sigue siendo válida.',
    confianza: 0,
    diagnostico_fallido: true
  };
} else {
  try {
    const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    diagnosis = JSON.parse(cleaned);
    diagnosis.diagnostico_fallido = false;
  } catch (e) {
    // La IA respondió, pero no con el JSON pedido.
    diagnosis = {
      diagnostico_visual: null,
      diagnostico_tecnico: 'La IA respondió en un formato inesperado.',
      severidad: 'desconocida',
      plagas_detectadas: [],
      acciones_inmediatas: ['Revisar manualmente el cultivo.'],
      recomendaciones_mediano_plazo: [],
      explicacion_agricultor: 'No se pudo interpretar la respuesta de la IA.',
      confianza: 0,
      diagnostico_fallido: true
    };
  }
}

// 4. Unimos los datos del cultivo con el diagnóstico
return [{ json: { ...cultivoData, diagnostico_ia: diagnosis } }];
